import { PasswordInput, Stack } from '@mantine/core';
import { SettingsForm } from './types';

interface SecurityTabProps {
  form: SettingsForm;
}

export function SecurityTab({ form }: SecurityTabProps) {
  return (
    <Stack>
      <PasswordInput
        size="md"
        label="New password"
        placeholder="At least 8 characters"
        withAsterisk
        {...form.getInputProps('password')}
      />

      <PasswordInput
        size="md"
        label="Confirm password"
        placeholder="Repeat the password"
        withAsterisk
        {...form.getInputProps('confirmPassword')}
      />
    </Stack>
  );
}

export type SettingsTab = 'profile' | 'security' | 'notifications';

export const TABS: { value: SettingsTab; label: string }[] = [
  { value: 'profile', label: 'Profile' },
  { value: 'security', label: 'Security' },
  { value: 'notifications', label: 'Notifications' },
];

export const TAB_FIELDS: Record<SettingsTab, string[]> = {
  profile: ['name', 'email'],
  security: ['password', 'confirmPassword'],
  notifications: ['emailNotifications', 'pushNotifications'],
};

import { UseFormReturnType } from '@mantine/form';

export interface SettingsValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  emailNotifications: boolean;
  pushNotifications: boolean;
}

export type SettingsForm = UseFormReturnType<SettingsValues>;
